package com.example.assets_management.security.scope; import com.example.assets_management.security.context.CurrentUserService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; @Service("ownScopeService") @RequiredArgsConstructor public class OwnScopeService { private final CurrentUserService current; public boolean isOwn(UUID userId){return userId!=null&&Objects.equals(userId,current.requireUserId());} public boolean isOwnOrPrivileged(UUID userId){return isOwn(userId)||current.getRoleName()!=null&&Set.of("Admin","Asset Manager").contains(current.getRoleName());} }
